const searchReports = `-- name: SearchReports :many
SELECT r.type, r.id, r.code, r.item_name, r.category_name, r.status, r.custody_status, r.place_name,
       r.occurred_at, r.person_name, r.relevance, r.created_at
FROM (
    SELECT 'lost'::text AS type, lr.id, lr.code, lr.item_name, c.name AS category_name, lr.status,
           NULL::text AS custody_status,
           coalesce((SELECT coalesce(l.name, z.name)
              FROM lost_report_places pl
              LEFT JOIN locations l ON l.id = pl.location_id
              LEFT JOIN zones z ON z.id = pl.zone_id
             WHERE pl.lost_report_id = lr.id
             ORDER BY pl.position LIMIT 1), '')::text AS place_name,
           lr.lost_until AS occurred_at,
           coalesce(u.full_name, lr.proxy_name, '')::text AS person_name,
           greatest(word_similarity(search_key($1::text), search_key(lr.item_name || ' ' || lr.description)),
                    word_similarity(search_key($1::text), search_key(coalesce(u.full_name, lr.proxy_name, ''))))::float8 AS relevance,
           lr.created_at
    FROM lost_reports lr
    JOIN categories c ON c.id = lr.category_id
    LEFT JOIN users u ON u.id = lr.reporter_id
    WHERE $2::bool
      AND lr.hidden_at IS NULL
      AND ($3::text IS NULL OR lr.code = $3::text)
      AND $4::text IS NULL
      AND $5::uuid IS NULL
      AND ($6::uuid IS NULL OR c.id = $6::uuid OR c.parent_id = $6::uuid)
      AND ($7::uuid IS NULL OR EXISTS (
            SELECT 1 FROM lost_report_places pl LEFT JOIN locations l ON l.id = pl.location_id
             WHERE pl.lost_report_id = lr.id AND coalesce(pl.zone_id, l.zone_id) = $7::uuid))
      AND ($8::uuid IS NULL OR EXISTS (
            SELECT 1 FROM lost_report_places pl WHERE pl.lost_report_id = lr.id AND pl.location_id = $8::uuid))
      AND ($9::timestamptz IS NULL OR lr.lost_until >= $9::timestamptz)
      AND ($10::timestamptz IS NULL OR lr.lost_from < $10::timestamptz)
      AND (cardinality($11::text[]) = 0 OR lr.status = ANY($11::text[]))
    UNION ALL
    SELECT 'found'::text, fr.id, fr.code, fr.item_name, c.name, fr.status,
           fr.custody_status,
           l.name,
           fr.found_at,
           coalesce(u.full_name, fr.proxy_finder_name, '')::text,
           greatest(word_similarity(search_key($1::text), search_key(fr.item_name || ' ' || fr.description)),
                    word_similarity(search_key($1::text), search_key(coalesce(u.full_name, fr.proxy_finder_name, ''))))::float8,
           fr.created_at
    FROM found_reports fr
    JOIN categories c ON c.id = fr.category_id
    JOIN locations l ON l.id = fr.found_location_id
    LEFT JOIN users u ON u.id = fr.finder_id
    WHERE $12::bool
      AND fr.hidden_at IS NULL
      AND ($3::text IS NULL OR fr.code = $3::text)
      AND ($4::text IS NULL OR fr.custody_status = $4::text)
      AND ($5::uuid IS NULL OR fr.holding_post_id = $5::uuid OR fr.intended_post_id = $5::uuid)
      AND ($6::uuid IS NULL OR c.id = $6::uuid OR c.parent_id = $6::uuid)
      AND ($7::uuid IS NULL OR l.zone_id = $7::uuid)
      AND ($8::uuid IS NULL OR fr.found_location_id = $8::uuid)
      AND ($9::timestamptz IS NULL OR fr.found_at >= $9::timestamptz)
      AND ($10::timestamptz IS NULL OR fr.found_at < $10::timestamptz)
      AND (cardinality($11::text[]) = 0 OR fr.status = ANY($11::text[]))
) r
WHERE $1::text = '' OR r.relevance >= 0.3
ORDER BY CASE WHEN $1::text = '' THEN 0 ELSE r.relevance END DESC, r.created_at DESC, r.id DESC
LIMIT $14 OFFSET $13
`

type SearchReportsParams struct {
	Term         string
	IncludeLost  bool
	Code         *string
	Custody      *string
	PostID       *uuid.UUID
	CategoryID   *uuid.UUID
	ZoneID       *uuid.UUID
	LocationID   *uuid.UUID
	FromTime     *time.Time
	ToTime       *time.Time
	Statuses     []string
	IncludeFound bool
	RowOffset    int32
	RowLimit     int32
}

type SearchReportsRow struct {
	Type          string
	ID            uuid.UUID
	Code          string
	ItemName      string
	CategoryName  string
	Status        string
	CustodyStatus *string
	PlaceName     string
	OccurredAt    time.Time
	PersonName    string
	Relevance     float64
	CreatedAt     time.Time
}

func (q *Queries) SearchReports(ctx context.Context, arg SearchReportsParams) ([]SearchReportsRow, error) {
	rows, err := q.db.Query(ctx, searchReports,
		arg.Term,
		arg.IncludeLost,
		arg.Code,
		arg.Custody,
		arg.PostID,
		arg.CategoryID,
		arg.ZoneID,
		arg.LocationID,
		arg.FromTime,
		arg.ToTime,
		arg.Statuses,
		arg.IncludeFound,
		arg.RowOffset,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchReportsRow{}
	for rows.Next() {
		var i SearchReportsRow
		if err := rows.Scan(
			&i.Type,
			&i.ID,
			&i.Code,
			&i.ItemName,
			&i.CategoryName,
			&i.Status,
			&i.CustodyStatus,
			&i.PlaceName,
			&i.OccurredAt,
			&i.PersonName,
			&i.Relevance,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

